/**
 * Result of malformed tool output detection.
 * - null = not malformed
 * - { retry: false, error: string } = malformed with a descriptive error (don't retry)
 * - { retry: true } = malformed, should retry
 */
type MalformedCheck =
  | null
  | { retry: true }
  | { retry: false; error: string };

function checkMalformedToolOutput(text: string): MalformedCheck {
  const trimmed = text.trim();
  if (!trimmed) {
    return { retry: true };
  }
  const lower = trimmed.toLowerCase();
  // Detect [object Object] from implicit toString() on a raw JS object.
  // This is the most common way tool authors accidentally serialize objects
  // instead of returning JSON.stringify() or a plain string.
  if (trimmed.includes("[object Object]")) {
    return {
      retry: false,
      error:
        "Tool returned '[object Object]' — this looks like an implicit toString() on a raw JavaScript object. " +
        "Return JSON.stringify(value) or a plain string instead. " +
        "See: https://docs.openclaw.ai/tools#return-values",
    };
  }
  if (/\bread\s*\[/.test(lower) || /\btool\b/.test(lower) || /\bfunction\b/.test(lower)) {
    return { retry: true };
  }
  return null;
}

export function shouldRetryToolReadProbe(params: {
  text: string;
  nonceA: string;
  nonceB: string;
  provider: string;
  attempt: number;
  maxAttempts: number;
}): boolean {
  if (params.attempt + 1 >= params.maxAttempts) {
    return false;
  }
  if (hasExpectedToolNonce(params.text, params.nonceA, params.nonceB)) {
    return false;
  }
  const malformed = checkMalformedToolOutput(params.text);
  if (malformed?.retry === false) {
    // Descriptive error already surfaced; don't retry.
    return false;
  }
  if (malformed?.retry === true) {
    return true;
  }
  if (params.provider === "anthropic" && isLikelyToolNonceRefusal(params.text)) {
    return true;
  }
  const lower = params.text.trim().toLowerCase();
  if (params.provider === "mistral" && (lower.includes("noncea=") || lower.includes("nonceb="))) {
    return true;
  }
  return false;
}

