export async function buildOllamaProvider(
  configuredBaseUrl?: string,
  opts?: { quiet?: boolean },
): Promise<ProviderConfig> {
  // Wrap the entire provider build in a 30-second timeout so that a hanging
  // Ollama server (e.g. a model that fails to load on constrained hardware)
  // cannot block model switching indefinitely. Without this, an unresponsive
  // Ollama endpoint causes the session transcript to inflate beyond the
  // context window, triggering a compaction loop that corrupts session state.
  // See: https://github.com/openclaw/openclaw/issues/57626
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 30_000);
  try {
    const models = await discoverOllamaModels(configuredBaseUrl, {
      ...opts,
      signal: controller.signal,
    });
    return {
      baseUrl: resolveOllamaApiBase(configuredBaseUrl),
      api: "ollama",
      models,
    };
  } catch (err) {
    if (controller.signal.aborted) {
      throw new Error(
        `Ollama provider (${resolveOllamaApiBase(configuredBaseUrl)}) did not respond within 30 seconds. ` +
          "Check that Ollama is running and the model is available. " +
          "You can also try switching to a different model or provider.",
      );
    }
    throw err;
  } finally {
    clearTimeout(timeoutId);
  }
}

