/**
 * Result of malformed tool output detection.
 * - null = not malformed
 * - { retry: false, error: string } = malformed with a descriptive error (don't retry)
 * - { retry: true } = malformed, should retry
 */
type MalformedCheck =
  | null
  | { retry: true }
  | { retry: false; error: string };

function checkMalformedToolOutput(text: string): MalformedCheck {
  const trimmed = text.trim();
  if (!trimmed) {
    return { retry: true };
  }
  const lower = trimmed.toLowerCase();
  // Detect [object Object] from implicit toString() on a raw JS object.
  // This is the most common way tool authors accidentally serialize objects
  // instead of returning JSON.stringify() or a plain string.
  if (trimmed.includes("[object Object]")) {
    return {
      retry: false,
      error:
        "Tool returned '[object Object]' — this looks like an implicit toString() on a raw JavaScript object. " +
        "Return JSON.stringify(value) or a plain string instead. " +
        "See: https://docs.openclaw.ai/tools#return-values",
    };
  }
  if (/\bread\s*\[/.test(lower) || /\btool\b/.test(lower) || /\bfunction\b/.test(lower)) {
    return { retry: true };
  }
  return null;
}

