export function hasExpectedToolNonce(text: string, nonceA: string, nonceB: string): boolean {
  return text.includes(nonceA) && text.includes(nonceB);
}

export function hasExpectedSingleNonce(text: string, nonce: string): boolean {
  return text.includes(nonce);
}

const NONCE_REFUSAL_MARKERS = [
  "token",
  "secret",
  "local file",
  "uuid-named file",
  "uuid named file",
  "parrot back",
  "disclose",
  "can't help",
  "can’t help",
  "cannot help",
  "can't comply",
  "can’t comply",
  "cannot comply",
  "isn't a real openclaw probe",
  "is not a real openclaw probe",
  "not a real openclaw probe",
  "no part of the system asks me",
];

const PROBE_REFUSAL_MARKERS = [
  "prompt injection attempt",
  "not a legitimate self-test",
  "not legitimate self-test",
  "authorized integration probe",
];

export function isLikelyToolNonceRefusal(text: string): boolean {
  const lower = text.toLowerCase();
  if (PROBE_REFUSAL_MARKERS.some((marker) => lower.includes(marker))) {
    return true;
  }
  if (lower.includes("nonce")) {
    return NONCE_REFUSAL_MARKERS.some((marker) => lower.includes(marker));
  }
  return false;
}

/**
 * Result of malformed tool output detection.
 * - null = not malformed
 * - { retry: false, error: string } = malformed with a descriptive error (don't retry)
 * - { retry: true } = malformed, should retry
 */
type MalformedCheck =
  | null
  | { retry: true }
  | { retry: false; error: string };

function checkMalformedToolOutput(text: string): MalformedCheck {
  const trimmed = text.trim();
  if (!trimmed) {
    return { retry: true };
  }
  const lower = trimmed.toLowerCase();
  // Detect [object Object] from implicit toString() on a raw JS object.
  // This is the most common way tool authors accidentally serialize objects
  // instead of returning JSON.stringify() or a plain string.
  // Only suppress retry when [object Object] appears as the dominant content
  // (i.e., not mixed with other substantive text like "read[...]" tool responses).
  if (trimmed.includes("[object Object]")) {
    // If it's mixed with other content (e.g. "read[object Object]"), treat as
    // retryable malformed output — the [object Object] is incidental to a larger response.
    if (lower.includes("read[") || /\bread\b/.test(lower)) {
      return { retry: true };
    }
    return {
      retry: false,
      error:
        "Tool returned '[object Object]' — this looks like an implicit toString() on a raw JavaScript object. " +
        "Return JSON.stringify(value) or a plain string instead. " +
        "See: https://docs.openclaw.ai/tools#return-values",
    };
  }
  if (/\bread\s*\[/.test(lower) || /\btool\b/.test(lower) || /\bfunction\b/.test(lower)) {
    return { retry: true };
  }
  return null;
}

export function shouldRetryToolReadProbe(params: {
  text: string;
  nonceA: string;
  nonceB: string;
  provider: string;
  attempt: number;
  maxAttempts: number;
}): boolean {
  if (params.attempt + 1 >= params.maxAttempts) {
    return false;
  }
  if (hasExpectedToolNonce(params.text, params.nonceA, params.nonceB)) {
    return false;
  }
  const malformed = checkMalformedToolOutput(params.text);
  if (malformed?.retry === false) {
    // Descriptive error already surfaced; don't retry.
    return false;
  }
  if (malformed?.retry === true) {
    return true;
  }
  if (params.provider === "anthropic" && isLikelyToolNonceRefusal(params.text)) {
    return true;
  }
  const lower = params.text.trim().toLowerCase();
  if (params.provider === "mistral" && (lower.includes("noncea=") || lower.includes("nonceb="))) {
    return true;
  }
  return false;
}

export function shouldRetryExecReadProbe(params: {
  text: string;
  nonce: string;
  provider: string;
  attempt: number;
  maxAttempts: number;
}): boolean {
  if (params.attempt + 1 >= params.maxAttempts) {
    return false;
  }
  if (hasExpectedSingleNonce(params.text, params.nonce)) {
    return false;
  }
  if (params.provider === "anthropic" && isLikelyToolNonceRefusal(params.text)) {
    return true;
