export async function buildOllamaProvider(
  configuredBaseUrl?: string,
  opts?: { quiet?: boolean },
): Promise<ProviderConfig> {
  // Wrap the entire provider build in a 30-second timeout so that a hanging
  // Ollama server (e.g. a model that fails to load on constrained hardware)
