  // context window, triggering a compaction loop that corrupts session state.
  // See: https://github.com/openclaw/openclaw/issues/57626
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 30_000);
  try {
    const models = await discoverOllamaModels(configuredBaseUrl, {
      ...opts,
      signal: controller.signal,
    });
    return {
      baseUrl: resolveOllamaApiBase(configuredBaseUrl),
      api: "ollama",
      models,
    };
  } catch (err) {
    if (controller.signal.aborted) {
      throw new Error(
        `Ollama provider (${resolveOllamaApiBase(configuredBaseUrl)}) did not respond within 30 seconds. ` +
          "Check that Ollama is running and the model is available. " +
          "You can also try switching to a different model or provider.",
      );
    }
    throw err;
  } finally {
    clearTimeout(timeoutId);
  }
}

